<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class Mauthmodel extends CI_Model {    function fnGetInfo($VarData = '', $VarStatus = '', $VarId = '', $VarCompanyId = '') {        $this->db->select('id,test_auth_name,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_MASTER_EXT_LAB);        if ($VarStatus <> '') {            $this->db->where_in('status', array($VarStatus));        } else {            $this->db->where_in('status', array(1, 2));        }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        if ($VarData <> '') {            $ArrWhere['test_auth_name'] = $VarData;        }        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheck($VarData = '', $VarId = '', $VarCompanyId = '') {        $this->db->from(KN_MASTER_EXT_LAB);        $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarData <> '') {            $ArrWhere['test_auth_name'] = $VarData;        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            unset($ArrUpdateData['id']);            $ArrCheckExist = $this->fnGetInfo($ArrUpdateData['test_auth_name'], 1, '', $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                $this->db->insert(KN_MASTER_EXT_LAB, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = 'This testing authority already exists';            }        } else {            $VarAlreadyExists = $this->fnCheck($ArrUpdateData['test_auth_name'], '', $ArrUpdateData['companyid']);            if (empty($VarAlreadyExists)) {                $this->db->update(KN_MASTER_EXT_LAB, $ArrUpdateData, array('id' => $VarId));                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = 'This testing authority already exists';            }        }        return $ArrResult;    }    function fnCount($VarSearch = '', $VarStatus = '') {        $userInfo = fnGetUserLoggedInfo(1);        $ArrWhere = array();        if ($VarSearch <> '') {            $ArrWhere[] = "test_auth_name like '%" . $VarSearch . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "l.status=" . $VarStatus;        } else {            $ArrWhere[] = "l.status in(1,2)";        }        $ArrWhere[] = "l.companyid = " . $userInfo['companyid'];        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere);        }        $VarSqlLab = "SELECT count(1) as trec  FROM " . KN_MASTER_EXT_LAB . " AS l INNER JOIN " . KN_USERS . " AS u ON l.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnList($VarSearch, $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder) {        $userInfo = fnGetUserLoggedInfo(1);        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('test_auth_name', 'l.status', 'u.contactname', 'l.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'l.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarSearch <> '') {            $ArrWhere[] = "test_auth_name like '%" . $VarSearch . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "l.status=" . $VarStatus;        } else {            $ArrWhere[] = "l.status in(1,2)";        }        $ArrWhere[] = "l.companyid = " . $userInfo['companyid'];        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere);        }        $VarSqlLab = "SELECT l.id,test_auth_name,u.contactname,l.dateupdated,l.status FROM " . KN_MASTER_EXT_LAB . " AS l INNER JOIN " . KN_USERS . " AS u ON l.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder . " limit " . $VarLimitInfo;        $ObjResult = $this->db->query($VarSqlLab);        return $ObjResult;    }    function fnChangeStat($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        return $this->db->update(KN_MASTER_EXT_LAB, array('status' => $optvalue));    }}